use super::{FIELD_HALF, MAX_BIT_BOUNDRY};

// p = 21888242871839275222246405745257275088548364400416034343698204186575808495617

/*
Numeric Generics Abreviations:
B   ->  BITS
SH  ->  SHIFT
M   ->  MAX_BITS
W   ->  WHOLE_BITS
D   ->  DECIMAL_BITS
R   ->  RESET
SK  ->  SIGN_KNOWN
SP  ->  SIGN_POS
RR  ->  RESET_ROUND
IR  ->  INV_ROUND
L0  ->  LAZY_ZERO_ADJUST
IP  ->  INV_PRECISION_BITS
LI  ->  LN_INPUT_BITS
LLB ->  LN_LAZY_BOUNDS
*/


// compute x/2
unconstrained fn halve(x: Field) -> Field{
    if is_pos_unc(x) == 1{
        (x - (x.sgn0() as Field)) / 2
    }else{
        (x - ((!x.sgn0()) as Field)) / 2
    }
}
global WHILE_FAIL: u32 = 10000;
// bin search for conditions that look like [False, False, ... True, True, ... True]
pub(crate) unconstrained fn bin_search<Env>(start: Field, end: Field, f: fn[Env](Field) -> bool) -> Field{
    let mut hi: Field = end;
    let mut lo: Field = start;
    let mut counter: u32 = 0;
    while lt_custom_all_unc(lo,hi){
        let mid: Field = halve(lo + hi);
        if f(mid as Field) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
        counter = counter +1;
        if counter >= WHILE_FAIL{
            assert(false, "Binary search very likely got stuck in a infinite cicle. This is a bug.");
        }
    }
    lo
}



// is positive function
pub unconstrained fn is_pos_unc(x: Field) -> Field{
    x.lt(FIELD_HALF + 1) as Field
}
// signed comparison for neg and pos numbers
pub unconstrained fn lt_custom_all_unc(a: Field, b: Field) -> bool{
    (a + FIELD_HALF).lt(b + FIELD_HALF)
}
// Returns if x is positive (0,1), it's sign (-1, 1) and its abs values
fn sign_abs_pos_unchecked(x: Field) -> (Field, Field, Field){
    (1Field, 1Field, x)
}
fn sign_abs_neg_unchecked(x: Field) -> (Field, Field, Field){
    (0Field, -1Field, -x)
}
fn sign_abs_sgnU_unchecked(x: Field) -> (Field, Field, Field){
    //Safety: hint is constrained by assert_max_bit_size::<1> but NOT checked (this must be done after if necessary)
    let isPos: Field = unsafe{is_pos_unc(x)}; 
    isPos.assert_max_bit_size::<1>();
    let sign: Field = 2Field * isPos - 1Field;
    let xAbs: Field = x * sign;
    (isPos, sign, xAbs) 
}
pub fn sign_abs_unchecked<let SK: u32, let SP: u32>(x: Field) -> (Field, Field, Field){
    if SK == 0{
        sign_abs_sgnU_unchecked(x)
    }else{
        if SP == 0{
            sign_abs_neg_unchecked(x)
        }else{
            sign_abs_pos_unchecked(x)
        }
    }
}

fn sign_abs_pos<let B: u32>(x: Field) -> (Field, Field, Field){
    let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_pos_unchecked(x);
    xAbs.assert_max_bit_size::<B>();
    (xIsPos, xSgn, xAbs)
}
fn sign_abs_neg<let B: u32>(x: Field) -> (Field, Field, Field){
    let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_neg_unchecked(x);
    xAbs.assert_max_bit_size::<B>();
    (xIsPos, xSgn, xAbs)
}
// the " + xIsPos - 1" is there to account for zero and enforce that zero is strictly not a negative value
fn sign_abs_sgnU<let B: u32>(x: Field) -> (Field, Field, Field){ 
    let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(x);
    (xAbs + xIsPos - 1).assert_max_bit_size::<B>();
    (xIsPos, xSgn, xAbs)
}
fn sign_abs_sgnU_unaccounted<let B: u32>(x: Field) -> (Field, Field, Field){ 
    let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(x);
    xAbs.assert_max_bit_size::<B>();
    (xIsPos, xSgn, xAbs)
}
pub fn sign_abs<let B: u32, let SK: u32, let SP: u32>(x: Field) -> (Field, Field, Field){
    if SK == 0{
        sign_abs_sgnU::<B>(x)
    }else{
        if SP == 0{
            sign_abs_neg::<B>(x)
        }else{
            sign_abs_pos::<B>(x)
        }
    }
}

// Check bit size internals
pub fn check_size<let B: u32, let SK: u32, let SP: u32>(x: Field){
    if SK == 0{
        // the " + xIsPos - 1" is there to account for zero and enforce that zero is strictly not a negative values
        let (xIsPos, _, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(x);
        (xAbs + xIsPos - 1).assert_max_bit_size::<B>();
    }else{
        if SP == 0{
            (-x).assert_max_bit_size::<B>();
        }else{
            x.assert_max_bit_size::<B>();
        }
    }
}

// Abs, Relu and Relu Derivative internals
// we can get away with not enforcing zero as positive since it doesnt cause diverging behaviour
pub fn abs_sgnU<let B: u32>(x: Field) -> Field{
    sign_abs_sgnU_unaccounted::<B>(x).2
}
pub fn relu_sgnU<let B: u32>(x: Field) -> Field{
    sign_abs_sgnU_unaccounted::<B>(x).0 * x
}
pub fn relu_der_sgnU<let B: u32>(x: Field) -> Field{
    sign_abs_sgnU_unaccounted::<B>(x).0
}

// greater than internals
pub fn gt_same_bits<let B: u32>(a: Field, b: Field) -> bool{
    sign_abs_sgnU::<B + 1>(a - b - 1).0 != 0
}
pub fn geqt_same_bits<let B: u32>(a: Field, b: Field) -> bool{
    sign_abs_sgnU::<B + 1>(a - b).0 != 0
}

// max and min internals
unconstrained fn max_unc<let N: u32>(arr: [Field; N]) -> u32 {
    let mut maxV: Field = arr[0];
    let mut idx: u32 = 0;
    for i in 1..N {
        // arr[i] > maxV
        if is_pos_unc(arr[i] - maxV - 1Field) == 1 {
            maxV = arr[i];
            idx = i;
        }
    }
    idx
}
unconstrained fn min_unc<let N: u32>(arr: [Field; N]) -> u32 {
    let mut minV: Field = arr[0];
    let mut idx: u32 = 0;
    for i in 1..N {
        // arr[i] < minV
        if is_pos_unc(minV - arr[i] - 1Field) == 1 {
            minV = arr[i];
            idx = i;
        }
    }
    idx
}
// The caller must verify that it is the maximum
pub fn max_unchecked<let N: u32>(arr: [Field; N]) -> Field {
    // Safety: dynamic indexing constrains the selected value to an element of arr. The caller verifies maximality
    let maxIdx: u32 = unsafe { max_unc(arr) };
    arr[maxIdx]
}
// The caller must verify that it is the minimum
pub fn min_unchecked<let N: u32>(arr: [Field; N]) -> Field {
    // Safety: dynamic indexing constrains the selected value to an element of arr. The caller verifies minimality
    let minIdx: u32 = unsafe { min_unc(arr) };
    arr[minIdx]
}



// code for bit shifting right
unconstrained fn reset_pos_unc<let SH: u32>(x: Field, B: u32) -> Field{
    let bits: [bool; 254] = x.to_le_bits::<254>();
    let mut res: Field = 0;
    let mut exp: Field = 1;
    for i in SH..B{
        res += exp * (bits[i] as Field);
        exp *= 2;
    }
    res
}
fn reset_pos_decompose<let B: u32, let SH: u32>(xPos: Field) -> (Field, Field){
    let POW_2_SHIFT: Field = 2Field.pow_32(SH as Field);
    // Safety: decomposition is properly checked below
    let x_MSB: Field = unsafe{reset_pos_unc::<SH>(xPos, B)};
    let x_LSB: Field = xPos - x_MSB * POW_2_SHIFT;
    (x_MSB, x_LSB)
}
//expects a positive input: [0, 2^B)
fn reset_pos_round<let B: u32, let SH: u32, let RR: u32>(xPos: Field) -> Field{
    let (x_MSB, x_LSB): (Field, Field) = reset_pos_decompose::<B, SH>(xPos);
    // Range check the limbs. 
    // NOTE: these also checks that x_MSB * 2^SH + x_LSB is less than the field modulus P.
    // Observe that x_MSB * 2^SH is at most MAX_BITS bits (usually 240) (less than P wich is 254).
    // Also observe that x_MSB * 2^SH + x_LSB is at most MAX_BITS + 1 bits (also less than P)
    // Therefore, since in this specific case congruance mod p is equivalent to equality, 
    // by the Division Algorithm we proove existance and uniquness for pair x_MSB (quotient) and x_LSB (reminder)
    x_MSB.assert_max_bit_size::<B - SH>();
    if RR == 0 {
        x_LSB.assert_max_bit_size::<SH>();
        x_MSB
    } else {
        // round to nearest
        let HALF: Field = 2Field.pow_32((SH - 1) as Field);
        // Safety: roundUp is properly checked and constrained
        let roundUp: Field = unsafe { is_pos_unc(x_LSB - HALF) };
        roundUp.assert_max_bit_size::<1>();
        (x_LSB - roundUp * HALF).assert_max_bit_size::<SH - 1>();
        x_MSB + roundUp
    }
}
pub fn reset<let B: u32, let SH: u32, let SK: u32, let SP: u32, let RR: u32>(x: Field) -> Field{
    if SK == 0{
        let (_, xSgn, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(x);
        xSgn * reset_pos_round::<B, SH, RR>(xAbs)
    }else{
        if SP == 0{
            -reset_pos_round::<B, SH, RR>(-x)
        }else{
            reset_pos_round::<B, SH, RR>(x)
        }
    }
}



// adjust zero and inv internals
unconstrained fn adj_0_strict_hint<let B: u32, let W: u32, let D: u32>(xAbs: Field) -> Field {
    let SMALL: Field = 2Field.pow_32((B - W - D) as Field);
    xAbs.lt(SMALL) as Field
}
fn adj_0_strict_l1(xAbs: Field) -> Field{
    xAbs + ((xAbs == 0) as Field)
}
fn adj_0_strict_l1_sgnU(xIsPos: Field, xAbs: Field) -> Field{
    // catches 0 edge case
    xAbs + ((xAbs == (xIsPos - 1)) as Field)
}
// we use this in some sign unknown cases to avoid an extra assert_bit_size
fn adj_0_strict_optimal_sgnU<let B: u32, let W: u32, let D: u32>(xIsPos: Field, xPos: Field) -> Field {
    let SMALL: Field = 2Field.pow_32((B - W - D) as Field);
    let POW_AUX: Field = 2Field.pow_32((W + D) as Field) - 1;
    // Safety: c is properly constrained and checked
    let c: Field = unsafe { adj_0_strict_hint::<B, W, D>(xPos) };
    c.assert_max_bit_size::<1>();
    let diff: Field = xPos - SMALL;
    let correction: Field = SMALL + POW_AUX * (xPos + xIsPos - 1);
    // Validates the clamp, sign hint, and canonical sign of zero
    (diff + c * correction).assert_max_bit_size::<B>();
    xPos - c * diff
}
fn adj_0_strict_base<let B: u32, let W: u32, let D: u32>(xAbs: Field) -> Field{
    let SMALL: Field = 2Field.pow_32((B - W - D) as Field);
    let diff: Field = xAbs - SMALL;
    // Safety: hint is properly constrained and checked
    let hint: Field = unsafe{is_pos_unc(diff)};
    hint.assert_max_bit_size::<1>();  
    // if hint == 1 {diff fits in BITS} else if hint == 0 {-diff fits in BITS}
    ((2Field * hint - 1Field) * diff).assert_max_bit_size::<B>();
    diff*hint + SMALL
}
fn adj_0_default_sgnK<let B: u32, let W: u32,  let D: u32, let L0: u32>(xAbs: Field) -> Field{
    if L0 == 0{
        if B == (W + D){
            adj_0_strict_l1(xAbs)
        }else{
            adj_0_strict_base::<B, W, D>(xAbs)
        }
    }else{
        let SMALL: Field = 2Field.pow_32((B - W - D) as Field);
        xAbs + SMALL
    }
}
fn adj_0_default_sgnU<let B: u32, let W: u32,  let D: u32, let L0: u32>(xIsPos: Field, xAbs: Field) -> Field{
    if L0 == 0{
        if B == (W + D){
            adj_0_strict_l1_sgnU(xIsPos, xAbs)
        }else if (B + W + D) <= MAX_BIT_BOUNDRY{
            adj_0_strict_optimal_sgnU::<B, W, D>(xIsPos, xAbs)
        }else{
            // weird edge case, where using the strict adjust zero (non lazy) introduces a vulnerability. Not only can 0
            // produce diverging behaviour but the sign of valid positive inputs can be maliciously swaped to negative
            // thus a stronger constraint is needed here
            (xAbs + xIsPos - 1).assert_max_bit_size::<B>();
            adj_0_strict_base::<B, W, D>(xAbs)
        }
    }else{
        // annoying zero edge case, if x is exactly zero an uncheked sign_abs_unchecked can create diverging behaviour for malicious prover
        assert((xAbs + xIsPos) != 0);
        let SMALL: Field = 2Field.pow_32((B - W - D) as Field);
        xAbs + SMALL
    }
}
fn adj_0_reset<let L0: u32>(xAbs: Field) -> Field{
    if L0 == 0{
        adj_0_strict_l1(xAbs)
    }else{
        xAbs + 1
    }
}
// basic long bit division
unconstrained fn long_div_unc(a: Field, b: Field) -> Field{
    let a_bits = a.to_be_bits::<254>();
    let mut q: Field = 0;
    let mut r: Field = 0;
    for i in 0..254{
        r = 2*r + (a_bits[i] as Field);
        q = 2*q;
        if is_pos_unc(r - b) == 1{
            r -= b;
            q += 1;
        }
    }
    q
}
// 1/x (expects x positive and BITS <= INV_MAX_BITS)
fn inv_pos<let B: u32, let W: u32, let D: u32, let IP: u32, let L0: u32, let IR: u32>(xPosNon0: Field) -> Field{
    let ONE: Field = 2Field.pow_32((B - W + IP) as Field) - 1;
    // Safety: q is properly constrained and checked
    let q: Field = unsafe{long_div_unc(ONE,xPosNon0)};
    let r: Field = ONE - xPosNon0 * q;

    // Note this always catches a negatvie value and fails
    q.assert_max_bit_size::<IP + D>();                  // constrict q to range, prevend x*q from overflow
    r.assert_max_bit_size::<B + L0>();                  // check that r is positive 
    let gap: Field = xPosNon0 - r - 1Field;
    gap.assert_max_bit_size::<B + L0>();                // check r < x
    if IR == 0{
        q
    }else{
        // Round up iff r + 1 >= gap
        let diff: Field = r + 1Field - gap;
        // Safety: roundUp is Boolean and its comparison is verified below.
        let roundUp: Field = unsafe { is_pos_unc(diff) };
        roundUp.assert_max_bit_size::<1>();
        // roundUp = 0: checks -diff - 1 >= 0 (strictly below halfway)
        // roundUp = 1: checks diff >= 0 (halfway or above)
        ((2Field * roundUp - 1Field) * diff + roundUp - 1Field).assert_max_bit_size::<B + L0 + 1>();
        q + roundUp
    }
}
pub fn inv<let B: u32, let SK: u32, let SP: u32,
    let W: u32, let D: u32, let IP: u32, let L0: u32, let IR: u32>(x: Field) -> Field
{
    if SK == 0{
        let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(x);
        let xAbsNon0: Field = adj_0_default_sgnU::<B, W, D, L0>(xIsPos, xAbs);
        xSgn * inv_pos::<B, W, D, IP, L0, IR>(xAbsNon0)
    }else{
        if SP == 0{
            let xAbsNon0: Field = adj_0_default_sgnK::<B, W, D, L0>(-x);
            -inv_pos::<B, W, D, IP, L0, IR>(xAbsNon0)
        }else{
            let xAbsNon0: Field = adj_0_default_sgnK::<B, W, D, L0>(x);
            inv_pos::<B, W, D, IP, L0, IR>(xAbsNon0)
        }
    }
}
pub fn inv_reset<let B: u32, let SK: u32, let SP: u32,
    let W: u32, let D: u32, let IP: u32, let L0: u32, let RR: u32, let IR: u32>(x: Field) -> Field
{
    if SK == 0{
        let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(x);
        // annoying zero edge case, if x is exactly zero an uncheked sign_abs can create diverging behaviour for malicious prover
        // here strict (non lazy) adjust zero doesn't have the same problem as inv_sgnU since reset() catches any sign shenanigans
        assert((xAbs + xIsPos) != 0);
        let xAbsAdj: Field = reset_pos_round::<B, B - W - D, RR>(xAbs);
        let xAbsAdjNon0: Field = adj_0_reset::<L0>(xAbsAdj);
        xSgn * inv_pos::<W + D, W, D, IP, L0, IR>(xAbsAdjNon0)
    }else{
        if SP == 0{
            let xAbsAdj: Field = reset_pos_round::<B, B - W - D, RR>(-x);
            let xAbsAdjNon0: Field = adj_0_reset::<L0>(xAbsAdj);
            -inv_pos::<W + D, W, D, IP, L0, IR>(xAbsAdjNon0)
        }else{
            let xAbsAdj: Field = reset_pos_round::<B, B - W - D, RR>(x);
            let xAbsAdjNon0: Field = adj_0_reset::<L0>(xAbsAdj);
            inv_pos::<W + D, W, D, IP, L0, IR>(xAbsAdjNon0)
        }
    }
}






// Square root internals
global POW_2_125: Field = 0x20000000000000000000000000000000;
unconstrained fn sqrt_pos_unc(x: Field) -> (Field, Field) {
    if is_pos_unc(x) == 1 {
        if x == 0 {
            (0Field, 0Field)
        } else if x == 1 {
            (1Field, 1Field)
        } else {
            let predicate = |mid: Field| x.lt(mid * mid);
            let s: Field = bin_search(0, POW_2_125 + 1, predicate) - 1Field;
            let r: Field = x - s*s;
            let s1: Field = if s.lt(r) {
                s + 1Field
            } else {
                s
            };
            (s1, s)
        }
    } else {
        // Invalid negative input, rejected by downstream constraints
        (0Field, 0Field)
    }
}
// fails if x is negative
pub fn sqrt<let BITS_EVEN_LVL: u32>(xPosEven: Field) -> Field {
    // s2 is the proposed integer square root, s1 is either s2 or s2 + 1.
    // Safety: both s1 and s2 are constrained and properly checked
    let (s1, s2): (Field, Field) = unsafe { sqrt_pos_unc(xPosEven) };
    let r: Field = xPosEven - s1 * s2;

    // make sure s1 == s2 or s1 == s2 + 1
    (s1 - s2).assert_max_bit_size::<1>();
    // Case [1]: r is positive only if s2 is indeed smaller or equals to sqrt(x) or
    // Case [2]: alternatively s1*s2 overflow and cause a positive r inspite being much larger than x
    r.assert_max_bit_size::<BITS_EVEN_LVL/2>();
    // if in case [1]: This completes the check and returns a proper integer square root with a bounded reminder
    // if in case [2]: This check always fails as s2 will be at least 126 bits, thus regardless of the size of r, it always
    // is greater than BITS_EVEN_LVL/2.
    (s2 - r).assert_max_bit_size::<BITS_EVEN_LVL/2>();
    s2
}
pub fn sqrt_reset<let B: u32, let W: u32, let D: u32, let RR: u32>(xPos: Field) -> Field{
    let xPosAdj: Field = reset_pos_round::<B, B - W - 2*D, RR>(xPos);
    sqrt::<W + 2*D>(xPosAdj)
}



// exp internal
use super::{EXP_POLY_BITS, EXP_K_BITS, EXP_K_MAX, EXP_LN2, EXP_INV_LN2_16};

global EXP_ONE_L6: Field = (1u128 << ((6 * EXP_POLY_BITS) as u128)) as Field;
global EXP_ONE_L5: Field = (1u128 << ((5 * EXP_POLY_BITS) as u128)) as Field;
global EXP_INV_2_L4: Field = (1u128 << ((4 * EXP_POLY_BITS - 1) as u128)) as Field;
global EXP_INV_6_L3: Field = ((1u128 << ((3 * EXP_POLY_BITS) as u128)) / 6) as Field;
global EXP_INV_24_L2: Field = ((1u128 << ((2 * EXP_POLY_BITS) as u128)) / 24) as Field;
global EXP_INV_120_L1: Field = 489; //adjusted taylor, previously: ((1u128 << (EXP_POLY_BITS as u128)) / 120) as Field;

global EXP_SGN_SCALE_DIFF: Field = ((1u64 << 32) - 2) as Field;

unconstrained fn to_bits_5_unc(k: Field) -> [Field; 5]{
    let k_u32: u32 = k as u32;
    [(k_u32 & 1) as Field,
    ((k_u32 >> 1) & 1) as Field,
    ((k_u32 >> 2) & 1) as Field,
    ((k_u32 >> 3) & 1) as Field,
    ((k_u32 >> 4) & 1) as Field]
}
fn pow_2_5bits(k: Field) -> Field {
    // Safety: the bit decomposition is verified below.
    let bits: [Field; 5] = unsafe { to_bits_5_unc(k) };
    bits[0].assert_max_bit_size::<1>();
    bits[1].assert_max_bit_size::<1>();
    bits[2].assert_max_bit_size::<1>();
    bits[3].assert_max_bit_size::<1>();
    bits[4].assert_max_bit_size::<1>();
    assert_eq(k, bits[0] + 2*bits[1] + 4*bits[2] + 8*bits[3] + 16*bits[4]);
    (1 + bits[0]) * (1 + 3*bits[1]) * (1 + 15*bits[2]) * (1 + 255*bits[3]) * (1 + 65535*bits[4])
}
// in: 16 fractional bits, out: 96 fractional bits.
fn exp_taylor(x: Field) -> Field {
    let x2: Field = x * x;
    let x3: Field = x2 * x;
    let x4: Field = x2 * x2;
    let x5: Field = x4 * x;
    EXP_ONE_L6 + x * EXP_ONE_L5 + x2 * EXP_INV_2_L4 + x3 * EXP_INV_6_L3 + x4 * EXP_INV_24_L2 + x5 * EXP_INV_120_L1
}
fn exp_adj_l1_internal<let D: u32>(xAdj: Field) -> (Field, Field){
    let EXP_M_UPSCALE: Field = (1 << (16 - D)) as Field;
    let EXP_INV_LN2: Field = (EXP_INV_LN2_16 >> (16 - D)) as Field;
    // xAdj and EXP_INV_LN2 are both level 1.
    let (k, r): (Field, Field) = reset_pos_decompose::<EXP_K_BITS + 2*D, 2*D>(xAdj * (EXP_INV_LN2 as Field));
    // Note we only check LSB here since MSB (aka "k") is automatically checked when performing pow_2_5bits
    r.assert_max_bit_size::<2*D>();

    // convert xAdj to the common 16-bit scale (improves D = 8 precision)
    let m: Field = xAdj * (EXP_M_UPSCALE as Field) - k * EXP_LN2;
    (k, m)
}
// fails if x is negative. Clamps values higher than established maximum
fn exp_adj_l1<let W: u32, let D: u32>(x: Field) -> (Field, Field) {
    let EXP_LIMIT_L1: Field = 22 * 2Field.pow_32(D as Field) - 1Field;
    let diff: Field = EXP_LIMIT_L1 - x;
    // Safety: the sign hint is constrained below.
    let isBelowLimit: Field = unsafe { is_pos_unc(diff) };
    isBelowLimit.assert_max_bit_size::<1>();
    ((2Field * isBelowLimit - 1Field) * diff).assert_max_bit_size::<W + D>();

    let xAdj: Field = EXP_LIMIT_L1 - isBelowLimit * diff;   // xAdj = min(x, EXP_LIMIT_L1)
    exp_adj_l1_internal::<D>(xAdj)
}
fn exp_l1_neg_wAbsValInpt<let W: u32, let D: u32>(xAbsLvl1: Field) -> Field {
    let (k, m): (Field, Field) = exp_adj_l1::<W, D>(xAbsLvl1);
    // the scaling happens when D = 8
    2Field * pow_2_5bits((EXP_K_MAX as Field) - k) * exp_taylor(-m)
}
fn exp_l1_sgnU_wAbsValInpt<let W: u32, let D: u32>(xIsPos: Field, xSgn: Field, xAbsLvl1: Field) -> Field {
    let (k, m): (Field, Field) = exp_adj_l1::<W, D>(xAbsLvl1);
    // pos: k,  neg: 31 - k
    let pow2Exponent: Field = (EXP_K_MAX as Field) - k + xIsPos * (2*k - (EXP_K_MAX as Field));
    // pos: 2^32,  neg: 2
    let scaleFactor: Field = 2Field + xIsPos * EXP_SGN_SCALE_DIFF;
    scaleFactor * pow_2_5bits(pow2Exponent) * exp_taylor(xSgn * m)
}
pub fn exp_l1<let SK: u32, let SP: u32, let W: u32, let D: u32>(xLvl1: Field) -> Field{
    if SK == 0{
        let (xIsPos, xSgn, xAbsLvl1): (Field, Field, Field) = sign_abs_sgnU_unchecked(xLvl1);
        exp_l1_sgnU_wAbsValInpt::<W, D>(xIsPos, xSgn, xAbsLvl1)
    }else{
        if SP == 0{
            exp_l1_neg_wAbsValInpt::<W, D>(-xLvl1)
        }else{
            let (k, m): (Field, Field) = exp_adj_l1::<W, D>(xLvl1);
            pow_2_5bits(k) * exp_taylor(m)
        }
    }
}
pub fn exp_reset<let B: u32, let SK: u32, let SP: u32, let W: u32, let D: u32, let RR: u32>(x: Field) -> Field{
    if SK == 0{
        let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(x);
        let xAbsLvl1: Field = reset_pos_round::<B, B - W - D, RR>(xAbs);
        exp_l1_sgnU_wAbsValInpt::<W, D>(xIsPos, xSgn, xAbsLvl1)
    }else{
        if SP == 0{
            let xPosLvl1: Field = reset_pos_round::<B, B - W - D, RR>(-x);
            exp_l1_neg_wAbsValInpt::<W, D>(xPosLvl1)
        }else{
            let xPosLvl1: Field = reset_pos_round::<B, B - W - D, RR>(x);
            let (k, m): (Field, Field) = exp_adj_l1::<W, D>(xPosLvl1);
            pow_2_5bits(k) * exp_taylor(m)
        }
    }
}


// natural log internals
fn exp_adj_l1_strict<let D: u32>(xAbsLvl1: Field) -> (Field, Field) {
    // prevent modular wraparound in the subsequent calculations.
    xAbsLvl1.assert_max_bit_size::<D + EXP_K_BITS>();
    exp_adj_l1_internal::<D>(xAbsLvl1)
}
// fails for values greater than max range
pub fn exp_l1_sgnU_strict<let D: u32>(xLvl1: Field) -> Field {
    let (xIsPos, xSgn, xAbs): (Field, Field, Field) = sign_abs_sgnU_unchecked(xLvl1);
    let (k, m): (Field, Field) = exp_adj_l1_strict::<D>(xAbs);
    // pos: k,  neg: 31 - k
    let pow2Exponent: Field = (EXP_K_MAX as Field) - k + xIsPos * (2*k - (EXP_K_MAX as Field));
    // pos: 2^32,  neg: 2
    let scaleFactor: Field = 2Field + xIsPos * EXP_SGN_SCALE_DIFF;
    scaleFactor * pow_2_5bits(pow2Exponent) * exp_taylor(xSgn * m)
}
unconstrained fn ln_l8_pos_unc<let D: u32>(x: Field) -> Field{  //EXP_LIMIT_L1
    if (x == 0) | (is_pos_unc(x) == 0){
        0
    }else{
        let predicate = |mid: Field| lt_custom_all_unc(x,exp_l1_sgnU_strict::<D>(mid));
        let EXP_LIM_F: Field = 22 * ((1u32 << D) as Field) - 1Field;
        bin_search(-EXP_LIM_F, EXP_LIM_F + 1, predicate) - 1Field
    }
}


// fails if x == 0 or x is negative
pub fn ln_l8<let D: u32, let LI: u32, let LLB: u32>(xPosLvl8: Field) -> Field{
    let POW_2_DB: Field = (1u32 << D) as Field;
    let E_LVL1: Field = if D == 8 { 258Field } else { 65548Field };

    xPosLvl8.assert_max_bit_size::<LI>(); // make sure x is positive and lvl 8
    // Safety: ln_x is constrained and checked properly
    let ln_x: Field = unsafe{ln_l8_pos_unc::<D>(xPosLvl8)};
    // Note exp_l1_sgnU_strict already checks that ln_x is in correct range. It fails otherwise

    let exp_ln_x: Field = exp_l1_sgnU_strict::<D>(ln_x);
    (xPosLvl8 - exp_ln_x).assert_max_bit_size::<LI>();
    if LLB == 0{
        let exp_ln_x_next: Field = exp_l1_sgnU_strict::<D>(ln_x + 1);
        (exp_ln_x_next - xPosLvl8 - 1Field).assert_max_bit_size::<LI>();
    }else{
        let exp_ln_x_next: Field = exp_ln_x * E_LVL1;
        (exp_ln_x_next - xPosLvl8 * POW_2_DB).assert_max_bit_size::<LI + D>();
    }
    ln_x
}
pub fn ln_reset<let B: u32, let D: u32, let LI: u32, let LLB: u32, let RR: u32>(xPos: Field) -> Field{
    let xPosLvl8: Field = reset_pos_round::<B, B - LI, RR>(xPos);
    ln_l8::<D, LI, LLB>(xPosLvl8)
}

