use super::ssfp_internal::{lt_custom_all_unc, check_size, max_unchecked, min_unchecked};


pub fn mat_from_arr<let M: u32, let N: u32>(arr: [Field; M*N]) -> [[Field; N]; M]{
    let mut res: [[Field; N]; M] = [[0; N]; M];
    for i in 0..M{
        let iN: u32 = i*N;
        for j in 0..N{
            res[i][j] = arr[iN + j];
        }
    }
    res
}
pub fn mat_new_from_slice<let M: u32, let N: u32, let START_ROW: u32, let START_COL: u32, let M_OG: u32, let N_OG: u32>
(mat: [[Field; N_OG]; M_OG]) -> [[Field; N]; M]{
    let mut res: [[Field; N]; M] = [[0; N]; M];
    for i in 0..M{
        for j in 0..N{
            res[i][j] = mat[START_ROW + i][START_COL + j]
        }
    }
    res
}



pub fn mat_check<let M: u32, let N: u32, let BITS: u32, let SK: u32, let SP: u32>(mat: [[Field; N]; M]){
    for i in 0..M{
        for j in 0..N{
            check_size::<BITS, SK, SP>(mat[i][j]);
        }
    }
}

unconstrained fn max_val_unc<let M: u32, let N: u32>(mat: [[Field; N]; M]) -> (Field, Field){
    let mut index_i: u32 = 0;
    let mut index_j: u32 = 0;
    let mut val: Field = mat[0][0];
    for i in 0..M{
        for j in 0..N{
            if lt_custom_all_unc(val, mat[i][j]){
                val = mat[i][j];
                index_i = i;
                index_j = j;
            }
        }
    }
    (index_i as Field, index_j as Field)
}
unconstrained fn min_val_unc<let M: u32, let N: u32>(mat: [[Field; N]; M]) -> (Field, Field){
    let mut index_i: u32 = 0;
    let mut index_j: u32 = 0;
    let mut val: Field = mat[0][0];
    for i in 0..M{
        for j in 0..N{
            if lt_custom_all_unc(mat[i][j], val){
                val = mat[i][j];
                index_i = i;
                index_j = j;
            }
        }
    }
    (index_i as Field, index_j as Field)
}
pub fn mat_max<let M: u32, let N: u32, let BITS: u32>(mat: [[Field; N]; M]) -> Field{
    // Safety: (idx_i, idx_j) is properly checked and constrained
    let (idx_i, idx_j): (Field, Field) = unsafe{max_val_unc(mat)};
    // ugly looking fix since I get a wrong "bug: Input to Brillig function is in a separate subgraph to output",
    // as far as I could test this gets around the incorrect error without adding any gates
    let maxVal: Field = mat[idx_i as u32][(idx_j + idx_i - idx_i) as u32];
    for i in 0..M{
        for j in 0..N{
            (maxVal - mat[i][j]).assert_max_bit_size::<BITS + 1>();
        }
    }
    maxVal
}
pub fn mat_min<let M: u32, let N: u32, let BITS: u32>(mat: [[Field; N]; M]) -> Field{
    // Safety: minVal is properly checked and constrained
    let (idx_i, idx_j): (Field, Field) = unsafe{min_val_unc(mat)};
    // ugly looking fix since I get a wrong "bug: Input to Brillig function is in a separate subgraph to output",
    // as far as I could test this gets around the incorrect error without adding any gates
    let minVal: Field = mat[idx_i as u32][(idx_j + idx_i - idx_i) as u32];
    for i in 0..M{
        for j in 0..N{
            (mat[i][j] - minVal).assert_max_bit_size::<BITS + 1>();
        }
    }
    minVal
}
pub fn mat_max_1N<let N: u32, let BITS: u32>(arr: [Field; N]) -> Field{
    let maxVal: Field = max_unchecked(arr);
    for i in 0..N{
        (maxVal - arr[i]).assert_max_bit_size::<BITS + 1>();
    }
    maxVal
}
pub fn mat_min_1N<let N: u32, let BITS: u32>(arr: [Field; N]) -> Field{
    let minVal: Field = min_unchecked(arr);
    for i in 0..N{
        (arr[i] - minVal).assert_max_bit_size::<BITS + 1>();
    }
    minVal
}



pub fn mat_transpose<let M: u32, let N: u32>(mat: [[Field; N]; M]) -> [[Field; M]; N]{
    let mut res: [[Field; M]; N] = [[0; M]; N];
    for i in 0..M{
        for j in 0..N{
            res[j][i] = mat[i][j];
        }
    }
    res
}


pub fn mat_add_all<let M: u32, let N: u32>(mat: [[Field; N]; M]) -> Field{
    let mut res: Field = 0;
    for i in 0..M{
        for j in 0..M{
            res += mat[i][j];
        }
    }
    res
}
pub fn mat_add_rows<let M: u32, let N: u32>(mat: [[Field; N]; M]) -> [[Field; N]; 1]{
    let mut res: [[Field; N]; 1] = [[0; N]; 1];
    for i in 0..M{
        for j in 0..N{
            res[0][j] = res[0][j] + mat[i][j];
        }
    }
    res
}
pub fn mat_add_cols<let M: u32, let N: u32>(mat: [[Field; N]; M]) -> [[Field; 1]; M]{
    let mut res: [[Field; 1]; M] = [[0; 1]; M];
    for i in 0..M{
        for j in 0..N{
            res[i][0] = res[i][0] + mat[i][j];
        }
    }
    res
}



// mat mult internals
pub fn mat_mult_nt_nt<let M: u32, let N: u32, let O: u32>(mat1: [[Field; N]; M], mat2: [[Field; O]; N]) -> [[Field; O]; M]{
    let mut res: [[Field; O]; M] = [[0; O]; M];
    for i in 0..M {
        for k in 0..N {
            for j in 0..O {
                res[i][j] += mat1[i][k] * mat2[k][j];
            }
        }
    }
    res
}
pub fn mat_mult_nt_t<let M: u32, let N: u32, let O: u32>(mat1: [[Field; N]; M], mat2: [[Field; N]; O]) -> [[Field; O]; M]{
    let mut res: [[Field; O]; M] = [[0; O]; M];
    for i in 0..M {
        for k in 0..N {
            for j in 0..O {
                res[i][j] += mat1[i][k] * mat2[j][k];
            }
        }
    }
    res
}
pub fn mat_mult_t_nt<let M: u32, let N: u32, let O: u32>(mat1: [[Field; M]; N], mat2: [[Field; O]; N]) -> [[Field; O]; M]{
    let mut res: [[Field; O]; M] = [[0; O]; M];
    for i in 0..M {
        for k in 0..N {
            for j in 0..O {
                res[i][j] += mat1[k][i] * mat2[k][j];
            }
        }
    }
    res
}
pub fn mat_mult_t_t<let M: u32, let N: u32, let O: u32>(mat1: [[Field; M]; N], mat2: [[Field; N]; O]) -> [[Field; O]; M]{
    let mut res: [[Field; O]; M] = [[0; O]; M];
    for i in 0..M {
        for k in 0..N {
            for j in 0..O {
                res[i][j] += mat1[k][i] * mat2[j][k];
            }
        }
    }
    res
}
